import{_ as o,r as s,o as p,c,e as a,a as l,s as r}from"./chunks/framework.CXcwiNg-.js";const m=JSON.parse('{"title":"模型 - October CMS - 3.x","titleTemplate":false,"description":"Tailor 提供的可用模型。","frontmatter":{"subtitle":"Tailor 提供的可用模型。"},"headers":[{"level":2,"title":"Entry 记录","slug":"entry-记录","link":"#entry-记录","children":[{"level":3,"title":"可用属性","slug":"可用属性","link":"#可用属性","children":[{"level":4,"title":"结构条目","slug":"结构条目","link":"#结构条目","children":[]},{"level":4,"title":"流条目","slug":"流条目","link":"#流条目","children":[]}]},{"level":3,"title":"检索多个条目","slug":"检索多个条目","link":"#检索多个条目","children":[]},{"level":3,"title":"检索单个条目","slug":"检索单个条目","link":"#检索单个条目","children":[]},{"level":3,"title":"插入和更新条目","slug":"插入和更新条目","link":"#插入和更新条目","children":[]}]},{"level":2,"title":"Global 记录","slug":"global-记录","link":"#global-记录","children":[{"level":3,"title":"可用属性","slug":"可用属性-1","link":"#可用属性-1","children":[]},{"level":3,"title":"检索 Global 记录","slug":"检索-global-记录","link":"#检索-global-记录","children":[]}]},{"level":2,"title":"使用关联字段","slug":"使用关联字段","link":"#使用关联字段","children":[{"level":3,"title":"预加载关联","slug":"预加载关联","link":"#预加载关联","children":[]},{"level":3,"title":"创建关联字段","slug":"创建关联字段","link":"#创建关联字段","children":[]}]},{"level":2,"title":"扩展模型构造函数","slug":"扩展模型构造函数","link":"#扩展模型构造函数","children":[]},{"level":2,"title":"扩展 Tailor 模型","slug":"扩展-tailor-模型","link":"#扩展-tailor-模型","children":[{"level":3,"title":"将 Tailor 关联到常规模型","slug":"将-tailor-关联到常规模型","link":"#将-tailor-关联到常规模型","children":[]},{"level":3,"title":"将常规模型关联到 Tailor","slug":"将常规模型关联到-tailor","link":"#将常规模型关联到-tailor","children":[]},{"level":3,"title":"构建自定义内容字段","slug":"构建自定义内容字段","link":"#构建自定义内容字段","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}]}],"relativePath":"3.x/zh-cn/cms/tailor/models.md","filePath":"3.x/zh-cn/cms/tailor/models.md"}'),i={name:"3.x/zh-cn/cms/tailor/models.md"};function d(u,n,k,g,h,b){const t=s("pre-heading"),e=s("post-heading");return p(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"模型",-1)),a(e),n[1]||(n[1]=r(`<p>本文介绍如何使用 PHP 与 Tailor 交互以及可用的模型。</p><h2 id="entry-记录"><a href="#entry-记录" class="header-anchor">#</a> Entry 记录</h2><p><code>Tailor\\Models\\EntryRecord</code> 模型用于存储条目的内容。</p><h3 id="可用属性"><a href="#可用属性" class="header-anchor">#</a> 可用属性</h3><p>除了您定义的表单字段外，还可以在检索的模型上找到以下属性。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>id</strong></td><td>数据库中的主键。</td></tr><tr><td><strong>blueprint_uuid</strong></td><td>关联蓝图的 UUID。</td></tr><tr><td><strong>content_group</strong></td><td>内容组名称（如果使用）。</td></tr><tr><td><strong>title</strong></td><td>条目的标题描述符，例如 <strong>My Blog Post</strong>。</td></tr><tr><td><strong>slug</strong></td><td>条目的 slug 标识符，例如 <code>my-blog-post</code>。</td></tr><tr><td><strong>is_enabled</strong></td><td>确定条目当前是否可见。</td></tr><tr><td><strong>created_at</strong></td><td>条目的创建日期。</td></tr><tr><td><strong>updated_at</strong></td><td>条目的最后更新日期。</td></tr><tr><td><strong>expired_at</strong></td><td>条目的过期日期。</td></tr><tr><td><strong>published_at</strong></td><td>条目的发布日期。</td></tr><tr><td><strong>published_at_date</strong></td><td>发布日期，如果未指定则为创建日期。</td></tr></tbody></table></div><h4 id="结构条目"><a href="#结构条目" class="header-anchor">#</a> 结构条目</h4><p>如果条目类型是 <code>structure</code>，它将具有一些额外属性。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>fullslug</strong></td><td>包含父级 slug 的 slug 标识符，例如 <code>parent-slug/child-slug</code>。</td></tr><tr><td><strong>parent</strong></td><td>此条目的父记录（如果可用）。</td></tr><tr><td><strong>children</strong></td><td>此条目的子记录（如果可用）。</td></tr></tbody></table></div><h4 id="流条目"><a href="#流条目" class="header-anchor">#</a> 流条目</h4><p>如果条目类型是 <code>stream</code>，它将具有一些额外属性。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>published_at_day</strong></td><td>条目发布的数字日期。</td></tr><tr><td><strong>published_at_month</strong></td><td>条目发布的数字月份。</td></tr><tr><td><strong>published_at_year</strong></td><td>条目发布的数字年份。</td></tr></tbody></table></div><h3 id="检索多个条目"><a href="#检索多个条目" class="header-anchor">#</a> 检索多个条目</h3><p>要使用 PHP 操作条目，您可以使用 <code>Tailor\\Models\\EntryRecord</code> 模型并调用 <code>inSection</code> 静态方法，传入 handle 以返回准备好的<a href="./../../extend/database/query.html">数据库模型查询</a>。或者，您可以使用 UUID 和 <code>inSectionUuid</code> 方法进行查找。</p><p>以下 <code>get</code> 方法查询返回<a href="./../../extend/services/collection.html">记录集合</a>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$records</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$records</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSectionUuid</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;a63fabaf-7c0b-4c74-b36f-7abf1a3ad1c1&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="检索单个条目"><a href="#检索单个条目" class="header-anchor">#</a> 检索单个条目</h3><p>结合 <code>where</code> 约束，您可以使用 <code>first</code> 方法查找单条记录。以下将查找 slug 等于 <strong>first-post</strong> 的条目。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$record</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;slug&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;first-post&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果<a href="./../tailor/blueprints.html">条目类型</a>设置为 <code>single</code>，您可以使用 <code>findSingleForSection</code> 方法来查找条目。同样，<code>findSingleForSectionUuid</code> 可用于通过 UUID 查找。这些方法将确保在查找期间记录存在。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$record</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">findSingleForSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Homepage&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$record</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">findSingleForSectionUuid</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;3328c303-7989-462e-b866-27e7037ba275&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="插入和更新条目"><a href="#插入和更新条目" class="header-anchor">#</a> 插入和更新条目</h3><p><code>inSection</code> 方法可用于动态创建记录。以下将创建一个新的博客文章条目。相同的代码可用于在首先检索到现有记录后更新它。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">title</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Imported Post&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="global-记录"><a href="#global-记录" class="header-anchor">#</a> Global 记录</h2><p><code>Tailor\\Models\\GlobalRecord</code> 模型用于存储全局的内容。</p><h3 id="可用属性-1"><a href="#可用属性-1" class="header-anchor">#</a> 可用属性</h3><p>除了定义的表单字段外，还可以在检索的模型上找到以下属性。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>id</strong></td><td>数据库中的主键。</td></tr><tr><td><strong>blueprint_uuid</strong></td><td>关联蓝图的 UUID。</td></tr></tbody></table></div><h3 id="检索-global-记录"><a href="#检索-global-记录" class="header-anchor">#</a> 检索 Global 记录</h3><p>要使用 PHP 查找全局，您可以使用 <code>Tailor\\Models\\GlobalRecord</code> 模型并调用 <code>findForGlobal</code> 静态方法，传入 handle。或者，您可以使用 UUID 和 <code>findForGlobalUuid</code> 方法进行查找。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">GlobalRecord</span><span class="token operator">::</span><span class="token function">findForGlobal</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Config&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">GlobalRecord</span><span class="token operator">::</span><span class="token function">findForGlobalUuid</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;7b193500-ac0b-481f-a79c-2a362646364d&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="使用关联字段"><a href="#使用关联字段" class="header-anchor">#</a> 使用关联字段</h2><p>关联字段可以包括 <a href="./../../element/form/widget-repeater.html">repeater 字段</a>和 <a href="./../../element/content/field-entries.html">entries 字段</a>，读写这些字段需要一些额外的步骤。</p><h3 id="预加载关联"><a href="#预加载关联" class="header-anchor">#</a> 预加载关联</h3><p>读取关联字段时，您可以使用 <code>load</code> 方法在集合上预加载它们。此方法将关联内容作为单次查询提供，性能最佳。</p><p>以下预加载 <strong>categories</strong> 字段并将其添加到结果中，同时包含传递多个关联字段的示例。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$records</span><span class="token operator">-&gt;</span><span class="token function">load</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;categories&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$records</span><span class="token operator">-&gt;</span><span class="token function">load</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;categories&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;author&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="创建关联字段"><a href="#创建关联字段" class="header-anchor">#</a> 创建关联字段</h3><p>写入关联字段时，您可以将关联名称作为方法调用以返回关系定义，然后可以调用后续的 <code>create()</code> 方法，该方法返回新创建的关联。</p><p>以下在 <strong>Blog\\Post</strong> 部分中找到第一篇博客文章，然后创建一个关联的分类。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">categories</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Test&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;price&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;100&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>使用 <code>make()</code> 方法创建一个新的空模型实例。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$category</span> <span class="token operator">=</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">categories</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果分类已经存在，请改用 <code>add()</code> 方法。以下将第一个博客分类添加到第一篇博客文章。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$category</span> <span class="token operator">=</span> <span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">inSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Category&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">categories</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token variable">$category</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>查看<a href="./../../extend/database/relations.html">关联文章</a>以了解更多关于模型关系的信息。</p></div><h2 id="扩展模型构造函数"><a href="#扩展模型构造函数" class="header-anchor">#</a> 扩展模型构造函数</h2><p>与<a href="./../../extend/extending.html">扩展常规模型</a>类似，您可以使用 <code>extendInSection</code> 方法扩展 <code>EntryRecord</code> 模型构造函数以定位特定蓝图。<code>extendInSectionUuid</code> 方法也可用于更精确的定位。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">EntryRecord</span><span class="token operator">::</span><span class="token function">extendInSection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.afterDelete&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Model has been deleted!</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>GlobalRecord</code> 模型构造函数也支持使用 <code>extendInGlobal</code> 和 <code>extendInGlobalUuid</code> 方法扩展以定位特定蓝图。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">GlobalRecord</span><span class="token operator">::</span><span class="token function">extendInGlobal</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Config&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.beforeSave&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Model has been saved!</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>如果未找到蓝图，<code>extendInSectionUuid</code> 和 <code>extendInGlobalUuid</code> 方法不会抛出异常。</p></div><h2 id="扩展-tailor-模型"><a href="#扩展-tailor-模型" class="header-anchor">#</a> 扩展 Tailor 模型</h2><p>在某些情况下，您可能希望将 Tailor 模型与<a href="./../../extend/system/models.html">常规数据库模型</a>结合使用。</p><h3 id="将-tailor-关联到常规模型"><a href="#将-tailor-关联到常规模型" class="header-anchor">#</a> 将 Tailor 关联到常规模型</h3><p><code>recordfinder</code> 表单字段为常规模型（例如插件定义的模型）引入关系定义。<strong>modelClass</strong> 应引用模型类，对于由 <strong>maxItems</strong> 指定的单数关系，<strong>list</strong> 属性是必需的。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">products</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Products
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Test\\Models\\Product
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/test/models/product/columns.yaml
    <span class="token key atrule">maxItems</span><span class="token punctuation">:</span> <span class="token number">1</span>
</code></pre></div><p>在此了解更多关于 <a href="./../../element/form/widget-recordfinder.html">record finder 表单小部件</a>的信息。</p><h3 id="将常规模型关联到-tailor"><a href="#将常规模型关联到-tailor" class="header-anchor">#</a> 将常规模型关联到 Tailor</h3><p>由于所有 Tailor 模型共享相同的模型类，因此在关系定义中需要一些额外的属性。<code>Tailor\\Traits\\BlueprintRelationModel</code> 实现了这些属性来引用 Tailor 模型，支持 Belongs To 和 Belongs To Many 关系。</p><p>当在模型中实现 <code>BlueprintRelationModel</code> trait 时，您可以提供 <code>blueprint</code> 属性以及引用 Tailor 蓝图的蓝图 UUID。以下将建立一个名为 <strong>author</strong> 的到 <code>Tailor\\Models\\EntryRecord</code> 类的 Belongs To 关系。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Product</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>Tailor<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>BlueprintRelationModel</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$belongsTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;author&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Tailor<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>EntryRecord</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;blueprint&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;6947ff28-b660-47d7-9240-24ca6d58aeae&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="构建自定义内容字段"><a href="#构建自定义内容字段" class="header-anchor">#</a> 构建自定义内容字段</h3><p>您还可以使用特定于实现的字段类型来引用常规模型，例如，自定义内容字段可能硬编码到 <code>Customer</code> 模型类。这涉及创建一个自定义 Tailor 字段，将提供对模型和数据库表的完全访问权限。</p><p>在内容字段类定义中，<code>extendModelObject</code> 方法允许内容字段扩展记录模型，<code>extendDatabaseTable</code> 用于向数据库表添加列。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">MyContentField</span> <span class="token keyword">extends</span> <span class="token class-name">ContentFieldBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">extendModelObject</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">belongsTo</span><span class="token punctuation">[</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">fieldName</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token class-name static-context">MyOtherModel</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">extendDatabaseTable</span><span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">fieldName</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39;_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>这需要更多的工作才能使事情运行起来，但结果是一个简单的字段 <strong>type</strong> 定义，配置最少。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">myfield</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> My Field
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mycontentfield
</code></pre></div><p>在此了解更多关于构建<a href="./../../extend/tailor-fields.html">自定义 Tailor 字段</a>的信息。</p><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4><div class="custom-block also"><ul><li><a href="./../../element/form/widget-recordfinder.html">RecordFinder 表单字段</a></li><li><a href="./../../extend/tailor-fields.html">构建 Tailor 字段</a></li></ul></div>`,72))])}const v=o(i,[["render",d]]);export{m as __pageData,v as default};
